#include "e189_snapshot.hpp"
#include <faiss/impl/ScalarQuantizer.h>
namespace e190 {
using namespace e189;
struct Meter190:Meter189 {uint64_t sq_scores=0;std::vector<uint64_t> sq_per_query;};
struct Scoring:Reuse {
 faiss::ScalarQuantizer sq;std::vector<uint8_t> sqcodes;std::vector<int32_t> idpos,wide;
 std::unique_ptr<faiss::ScalarQuantizer::SQDistanceComputer> sqdc;
 Scoring(const json& c):Reuse(c),sq(old.d,faiss::ScalarQuantizer::QT_8bit){
  fs::path p=c.at("sq8");sq.trained=read_raw<float>((p/"trained.f32").string());sqcodes=read_raw<uint8_t>((p/"block_sq8.u8").string());
  require(sq.trained.size()==2*old.d&&sqcodes.size()==old.N*old.d,"SQ8 layout");sqdc.reset(sq.get_distance_computer(faiss::MetricType(old.metric)));
  idpos.resize(old.N);for(size_t i=0;i<bl.ids.size();++i)idpos[bl.ids[i]]=i;wide.reserve(384);heap.reserve(384);all.reserve(8192);
 }
 float sqscore(size_t i) {float v=sqdc->query_to_code(sqcodes.data()+i*old.d);return old.metric==0?-v:v;}
 void push_sq(int32_t id,size_t pos,uint64_t arrival,bool oracle){A a{sqscore(pos),arrival,id};if(oracle)all.push_back(a);else if(heap.size()<96){heap.push_back(a);std::push_heap(heap.begin(),heap.end(),e187::Backend::Less{});}else if(e187::Backend::approx_less(a,heap.front())){std::pop_heap(heap.begin(),heap.end(),e187::Backend::Less{});heap.back()=a;std::push_heap(heap.begin(),heap.end(),e187::Backend::Less{});}}
 void complete190(faiss::DistanceComputer& dc,const float* q,int32_t* R,float* D,const int32_t* hubs,const std::string& m,Meter190& st,bool oracle=false){
  wide.clear();if(m=="REUSE-BLOCK"){complete189(dc,q,R,D,hubs,m,st,oracle);return;}
  require(m=="SQ8-96"||m=="PQ384-SQ8","known E190 method");bool cascade=m=="PQ384-SQ8";
  proposals(R,hubs,false,false);block_rank.clear();for(int b:pool)block_rank.emplace_back(old.score(q,bl.cent.data()+b*old.d,old.d),b);std::sort(block_rank.begin(),block_rank.end());st.blocks+=block_rank.size();
  if(cascade)prepare<false>(q,R,100,st);else{sorted.assign(R,R+100);std::sort(sorted.begin(),sorted.end());candidates.clear();}
  sqdc->set_query(q);heap.clear();all.clear();size_t consumed=0;uint64_t arrival=0;
  for(auto [score,b]:block_rank){size_t len=bl.off[b+1]-bl.off[b];if(consumed+len>2048)continue;scan_blocks.push_back(b);
   for(size_t i=bl.off[b];i<bl.off[b+1];++i,++arrival){int32_t id=bl.ids[i];if(cascade)offer(id,bl.codes.data()+16*i,arrival,384,oracle);else if(!std::binary_search(sorted.begin(),sorted.end(),id)){push_sq(id,i,arrival,oracle);++st.sq_scores;}}
   consumed+=len;if(consumed==2048)break;
  }st.scans+=consumed;
  if(cascade){finish(384,oracle);wide=candidates;candidates.clear();heap.clear();all.clear();for(size_t j=0;j<wide.size();++j){push_sq(wide[j],idpos[wide[j]],j,oracle);++st.sq_scores;}}
  finish(96,oracle);require(candidates.size()<=96&&consumed<=2048,"scoring hard budget");refine<false>(dc,R,D,100,st,oracle);
 }
};
void run190(acsg::IndexACSGFlat& idx,const std::vector<float>& q,int L,const std::string& m,Router& router,Posting& post,Scoring& e,Batch& b,Meter190& st){
 if(m=="GT10"||m=="B32"||m=="REUSE-BLOCK"){run189(idx,q,L,m,router,post,e,b,st);return;}
 idx.acsg.search_L=L;std::vector<std::vector<acsg::EnterPoint>> eps(b.n);for(size_t i=0;i<b.n;++i){auto r=router.route(q.data()+i*idx.d);for(int j=0;j<3;++j){b.entries[3*i+j]=r.ids[j];b.profile_distances[3*i+j]=r.distances[j];eps[i].emplace_back(r.ids[j],1.f);}}
 faiss::VisitedTable vt(idx.ntotal);std::unique_ptr<faiss::DistanceComputer> dc(acsg::storage_distance_computer(idx.storage));std::vector<acsg::Neighbor> ret;std::vector<faiss::idx_t> ids(100);std::vector<int32_t> cur(100);st.per_query.reserve(b.n*3);st.sq_per_query.reserve(b.n);
 for(size_t i=0;i<b.n;++i){const float* qi=q.data()+i*idx.d;dc->set_query(qi);vt.advance();idx.acsg.search_new(*dc,100,ids.data(),b.distances.data()+i*100,vt,2,eps[i],&ret);for(size_t j=0;j<100;++j)cur[j]=ids[j];auto ns=st.scans,nb=st.blocks,ne=st.exact,nq=st.sq_scores;e.complete190(*dc,qi,cur.data(),b.distances.data()+i*100,b.entries.data()+3*i,m,st);std::copy(cur.begin(),cur.end(),b.ids.begin()+i*100);st.per_query.insert(st.per_query.end(),{st.scans-ns,st.blocks-nb,st.exact-ne});st.sq_per_query.push_back(st.sq_scores-nq);}
}
__attribute__((noinline)) double timed190(acsg::IndexACSGFlat& idx,const std::vector<float>& q,int L,const std::string& m,Router& r,Posting& p,Scoring& e,Batch& dest,Meter190& st){auto t=Clock::now();{Batch out(dest.n,dest.k);run190(idx,q,L,m,r,p,e,out,st);copy_packet(out,dest);asm volatile("" : : "g"(out.ids.data()),"g"(dest.ids.data()) : "memory");}return seconds(t);}
json prepare_sq(const json& c){check_threads(c);auto t=Clock::now();Matrix mat(c.at("base"));auto x=mat.copy();faiss::ScalarQuantizer sq(mat.d,faiss::ScalarQuantizer::QT_8bit);sq.train(mat.n,x.data());std::vector<uint8_t> codes(mat.n*mat.d),ordered(codes.size());sq.compute_codes(x.data(),codes.data(),mat.n);auto ids=read_raw<int32_t>((fs::path(c.at("blocks"))/"block_ids.i32").string());for(size_t i=0;i<mat.n;++i)std::copy(codes.begin()+size_t(ids[i])*mat.d,codes.begin()+(size_t(ids[i])+1)*mat.d,ordered.begin()+i*mat.d);fs::path out=c.at("sq8");write_raw(out/"trained.f32",sq.trained);write_raw(out/"block_sq8.u8",ordered);json rec={{"status","PASS_E190_SQ8_PREPARATION"},{"N",mat.n},{"d",mat.d},{"code_bytes",ordered.size()},{"trained_bytes",sq.trained.size()*4},{"range","RS_minmax arg0"},{"training","all original base, no query or GT"},{"seconds",seconds(t)},{"threads",process_threads()}};fresh_json(out/"sq8.json",rec);return rec;}
json benchmark190(const json& c,bool qualify){check_threads(c);auto began=Clock::now();fs::path root=c.at("output_dir");fresh_dir(root);fresh_json(root/"config.json",c);json binding;auto idx=load_index(c,binding);Matrix qm(c.at("queries"));auto q=qm.copy();Router router(c.at("router"),idx->d,idx->ntotal);Posting post(c.at("table"),idx->ntotal);Scoring e(c);
 fresh_json(root/"environment.json",{{"threads",process_threads()},{"cpu",15},{"binding",binding},{"old_backend_bytes",e.old.bytes()},{"block_backend_bytes",e.bl.bytes()},{"reuse_array_bytes",e.id_block.size()*4+e.hub_regions.size()*4+e.hub_blocks.size()*4},{"sq8_code_bytes",e.sqcodes.size()},{"sq8_trained_bytes",e.sq.trained.size()*4},{"sq8_idpos_bytes",e.idpos.size()*4},{"timer","full Batch allocation/init + unchanged route/main + completion + six-array copy + destruction"},{"startup_seconds",seconds(began)}});
 std::set<int> cl;for(int L:c.at("completion_L"))cl.insert(L);json results=json::array(),progress=json::array();size_t ordinal=0,batches=0;int repeats=qualify?1:3;
 for(int L:c.at("main_L")){std::vector<std::string> methods={"GT10"};if(cl.count(L))methods=c.at("methods").get<std::vector<std::string>>();std::vector<std::unique_ptr<Batch>> first(methods.size());std::vector<json> rounds(methods.size(),json::array());std::vector<Meter190> meters(methods.size());Batch archive(qm.n,100);
  for(int rep=0;rep<repeats;++rep)for(size_t off=0;off<methods.size();++off){size_t mi=(ordinal+rep+off)%methods.size();auto m=methods[mi];check_threads(c);fs::path point=root/(m+"_L"+std::to_string(L));if(rep==0){Batch warm(std::min<size_t>(qm.n,256),100);Meter190 st;run190(*idx,q,L,m,router,post,e,warm,st);}Meter190 st;double wall=timed190(*idx,q,L,m,router,post,e,archive,st);++batches;check_threads(c);validate(archive,idx->ntotal);auto digest=packet_sha(archive);
   if(rep==0){first[mi]=std::make_unique<Batch>(archive);archive.save(point/"raw",false);meters[mi]=st;if(!st.per_query.empty())write_raw(point/"access.u64",st.per_query);if(!st.coarse_per_query.empty())write_raw(point/"coarse.u32",st.coarse_per_query);if(!st.sq_per_query.empty())write_raw(point/"sq_scores.u64",st.sq_per_query);}else all_same(*first[mi],archive);
   json r={{"round",rep},{"wall_seconds",wall},{"qps",qm.n/wall},{"packet_sha256",digest},{"threads",process_threads()},{"scanned_codes",st.scans},{"extra_exact_scores",st.exact},{"block_centres",st.blocks},{"coarse_centres",st.coarse},{"sq8_scores",st.sq_scores}};if(rep)require(digest==rounds[mi][0].at("packet_sha256"),"round SHA");rounds[mi].push_back(r);fresh_json(point/("round"+std::to_string(rep)+".json"),r);json ev={{"dataset",c.at("dataset")},{"method",m},{"L",L},{"round",rep},{"qps",qm.n/wall}};progress.push_back(ev);write_json(root/"progress.json",progress);std::cout<<ev.dump()<<std::endl;
  }
  if(cl.count(L)){require(methods[0]=="GT10","main first");std::unique_ptr<faiss::DistanceComputer> dc(acsg::storage_distance_computer(idx->storage));for(size_t mi=1;mi<methods.size();++mi){auto m=methods[mi];if(m=="B32"){audit_merge(*idx,q,*first[0],*first[mi],post);continue;}std::vector<int32_t> trace;bool tracing=true;if(tracing)trace.assign(qm.n*160,-1);std::vector<int32_t> wide_trace;if(c.value("wide_diagnostic",false)&&L==200&&m=="REUSE-BLOCK")wide_trace.assign(qm.n*384,-1);
    for(size_t i=0;i<qm.n;++i){require(first[0]->entries==first[mi]->entries,"same routes");std::vector<int32_t> rr(first[0]->ids.begin()+i*100,first[0]->ids.begin()+(i+1)*100);std::vector<float> dd(first[0]->distances.begin()+i*100,first[0]->distances.begin()+(i+1)*100);dc->set_query(q.data()+i*idx->d);Meter190 st;e.complete190(*dc,q.data()+i*idx->d,rr.data(),dd.data(),first[0]->entries.data()+3*i,m,st,true);
     for(size_t j=0;j<100;++j)require(rr[j]==first[mi]->ids[i*100+j]&&equal_float(dd[j],first[mi]->distances[i*100+j]),"actual main + exhaustive bounded PQ + full-sort merge oracle");
     if(tracing){std::copy(e.pool.begin(),e.pool.end(),trace.begin()+i*160);std::copy(e.scan_blocks.begin(),e.scan_blocks.end(),trace.begin()+i*160+32);std::copy(e.candidates.begin(),e.candidates.end(),trace.begin()+i*160+64);}if(!wide_trace.empty()){Meter190 wide_st;std::vector<int32_t> wrr(first[0]->ids.begin()+i*100,first[0]->ids.begin()+(i+1)*100);std::vector<float>wdd(first[0]->distances.begin()+i*100,first[0]->distances.begin()+(i+1)*100);e.complete190(*dc,q.data()+i*idx->d,wrr.data(),wdd.data(),first[0]->entries.data()+3*i,"PQ384-SQ8",wide_st,true);std::copy(e.wide.begin(),e.wide.end(),wide_trace.begin()+i*384);}
    }if(tracing)write_raw(root/(m+"_L"+std::to_string(L)+"/trace.i32"),trace);if(!wide_trace.empty())write_raw(root/"PQ384_diagnostic_L200.i32",wide_trace);
   }}
  for(size_t mi=0;mi<methods.size();++mi){std::vector<double>w;for(auto r:rounds[mi])w.push_back(r.at("wall_seconds"));std::sort(w.begin(),w.end());auto m=methods[mi];fs::path point=root/(m+"_L"+std::to_string(L));json r={{"status","PASS_E190_POINT"},{"dataset",c.at("dataset")},{"method",m},{"K",100},{"L",L},{"n",qm.n},{"qps",qm.n/w[w.size()/2]},{"rounds",rounds[mi]},{"timed_output_retained",true},{"all_round_bits_equal",true},{"merge_oracle_passed",cl.count(L)>0&&mi>0},{"result_dir",point.string()},{"scanned_codes_per_query",double(meters[mi].scans)/qm.n},{"extra_exact_scores_per_query",double(meters[mi].exact)/qm.n},{"block_centres_per_query",double(meters[mi].blocks)/qm.n},{"coarse_centres_per_query",double(meters[mi].coarse)/qm.n},{"sq8_scores_per_query",double(meters[mi].sq_scores)/qm.n}};fresh_json(point/"result.json",r);results.push_back(r);}++ordinal;
 }
 json r={{"status",qualify?"PASS_E190_QUALIFICATION":"PASS_E190_MATRIX"},{"dataset",c.at("dataset")},{"points",results.size()},{"batches",batches},{"n",qm.n},{"results",results},{"outer_seconds",seconds(began)},{"evaluation_GT_read",false},{"threads",1}};fresh_json(root/"complete.json",r);return r;
}
}
int main(int argc,char**argv){try{using namespace e190;require(argc==3,"mode config");auto c=read_json(argv[2]);std::string m=argv[1];auto r=m=="prepare"?prepare_sq(c):benchmark190(c,m=="qualification");std::cout<<r.dump()<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<"FATAL E190 "<<e.what()<<std::endl;return 2;}}
